const input = $input.first().json;
const plans = [];
let remaining = Math.max(0, input.per_run_call_limit - input.run_call_count);
for (const company of input.companies || []) {
  const siren = String(company.siren || '').replace(/\D/g, '');
  const cache = input.cache_by_siren[siren] || null;
  let status = 'not_eligible'; let reason = 'G8N_PAPPERS_NOT_ELIGIBLE'; let api_call_count = 0;
  if (!input.enabled) { status = 'disabled'; reason = 'G8N_PAPPERS_DISABLED'; }
  else if (!siren || siren.length !== 9 || !company.company_key) { status = 'not_eligible'; reason = 'G8N_PAPPERS_MISSING_SIREN'; }
  else if ((company.identity_confidence || 0) < 85 || (company.active_offer_count || 0) < 2 || company.review_pending) { status = 'not_eligible'; reason = 'G8N_PAPPERS_GATE_FAILED'; }
  else if (cache && cache.expires_at && new Date(cache.expires_at) > new Date(input.now_utc)) { status = 'cache_hit'; reason = 'G8N_PAPPERS_CACHE_HIT'; }
  else if (remaining <= 0) { status = 'deferred'; reason = 'G8N_PAPPERS_BUDGET_REACHED'; }
  else { status = 'enriched'; reason = 'G8N_PAPPERS_CALL_PLANNED'; api_call_count = 1; remaining -= 1; }
  plans.push({ company_key: company.company_key, siren, enrichment_status: status, reason, api_call_count, cache_key: siren ? `siren:${siren}` : null, request_contract: status === 'enriched' ? { credential_name: 'Pappers API — local', whitelist_only: true } : null });
}
return [{ json: { ...input, pappers_enrichment_plans: plans, planned_api_call_count: plans.reduce((s, p) => s + p.api_call_count, 0) } }];
